export function LayoutComponent({
  layoutType = "{{layoutType}}",
  gap = {{gap}},
  accent = "{{accent}}",
  showBorders = {{showBorders}},
}) {
  const boxStyle = layoutType === "grid"
    ? { display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap }
    : { display: "flex", flexDirection: layoutType === "stack" ? "column" : "row", gap };
  const item = { display: "flex", alignItems: "center", justifyContent: "center", width: layoutType === "grid" ? "auto" : 44, height: 44, borderRadius: 6, fontWeight: 700, background: accent };
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>&lt;{layoutType} gap={gap}&gt;</p>
      <div style={{ ...boxStyle, boxSizing: "border-box", padding: 8, border: showBorders ? "1.5px dashed #24143030" : "none", borderRadius: showBorders ? 8 : 0 }}>
        <span style={item}>A</span>
        <span style={item}>B</span>
        <span style={item}>C</span>
      </div>
    </div>
  );
}
